/*
 * A054584  Number of subgroups of the group generated by a^n=1, b^3=1 and
 *          ab=ba.
 * https://oeis.org/A054584
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, nice
 * Formula:   a(n) = 2*tau(n) if n mod 3 != 0; a(n) = 2*(tau(n)+tau(n/3)) if n
 *            mod 3 == 0 where tau(m) = number of divisors of m
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   factor_u64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include "../utils/factor_u64.h"

static seq_t tau_u64(uint64_t m)
{
    /* factor_u64 fills arrays with prime factors and exponents */
    size_t cnt;
    uint64_t pr[64], ex[64];
    factor_u64(m, pr, ex, &cnt);
    seq_t t = 1;
    for (size_t i = 0; i < cnt; ++i)
        t = t * (seq_t)(ex[i] + 1);
    return t;
}

seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* offset starts at 1, but guard anyway */
    seq_t tau_n = tau_u64((uint64_t)n);
    if (n % 3 == 0) {
        seq_t tau_n3 = tau_u64((uint64_t)(n / 3));
        return 2 * tau_n + 2 * tau_n3;
    } else {
        return 2 * tau_n;
    }
}
